import{_ as r,a0 as p,w as o,s as d,I as n,x as t,a1 as i,A as a,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions","title":"如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务","tag":"201912","desc":""},"relativePath":"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),u={name:"201912/20191220 How to Start, Stop - Restart Services in Ubuntu and Other Linux Distributions.md"};function h(g,s,b,c,k,m){const e=p("Link");return o(),d("div",null,[s[23]||(s[23]=n("h1",{id:"如何在-ubuntu-和其他-linux-发行版中启动、停止和重启服务",tabindex:"-1"},[t("如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务 "),n("a",{class:"header-anchor",href:"#如何在-ubuntu-和其他-linux-发行版中启动、停止和重启服务","aria-label":"Permalink to “如何在 Ubuntu 和其他 Linux 发行版中启动、停止和重启服务”"},"​")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/28/081645vee5lkult55kituu.jpg",alt:""})],-1)),n("p",null,[s[2]||(s[2]=t("服务是必不可少的后台进程，它通常随系统启动，并在关机时关闭。如果你是系统管理员，那么你会定期处理服务。如果你是普通桌面用户，你可能会遇到需要重启服务的情况，例如",-1)),i(e,{href:"https://itsfoss.com/keyboard-mouse-sharing-between-computers/"},{default:a(()=>[...s[0]||(s[0]=[t("安装 Barrier 来用于在计算机之间共享鼠标和键盘",-1)])]),_:1}),s[3]||(s[3]=t("。或",-1)),i(e,{href:"https://itsfoss.com/set-up-firewall-gufw/"},{default:a(()=>[...s[1]||(s[1]=[t("在使用 ufw 设置防火墙",-1)])]),_:1}),s[4]||(s[4]=t("时。",-1))]),s[25]||(s[25]=l('<p>今天，我将向你展示两种管理服务的方式。你将学习在 Ubuntu 或任何其他 Linux 发行版中启动、停止和重启服务。</p><blockquote><p>systemd 与 init</p><p>如今，Ubuntu 和许多其他发行版都使用 systemd 而不是旧的 init。</p><p>在 systemd 中，可以使用 <code>systemctl</code> 命令管理服务。</p><p>在 init 中，你可以使用 <code>service</code> 命令管理服务。</p><p>你会注意到，即使你的 Linux 系统使用 systemd，它仍然可以使用 <code>service</code> 命令（与 init 系统一起使用的）。这是因为 <code>service</code> 命令实际上已重定向到 <code>systemctl</code>。systemd 引入了向后兼容性，因为系统管理员们习惯使用 <code>service</code> 命令。</p><p>在本教程中，我将同时展示 <code>systemctl</code> 和 <code>service</code> 命令。</p></blockquote><p>我用的是 Ubuntu 18.04，但其他版本的过程也一样。</p><h3 id="方法-1-使用-systemd-在-linux-中管理服务" tabindex="-1">方法 1：使用 systemd 在 Linux 中管理服务 <a class="header-anchor" href="#方法-1-使用-systemd-在-linux-中管理服务" aria-label="Permalink to “方法 1：使用 systemd 在 Linux 中管理服务”">​</a></h3><p>我从 systemd 开始，因为它被广泛接受。</p><h4 id="_1、列出所有服务" tabindex="-1">1、列出所有服务 <a class="header-anchor" href="#_1、列出所有服务" aria-label="Permalink to “1、列出所有服务”">​</a></h4><p>为了管理服务，你首先需要知道系统上有哪些服务可用。你可以使用 systemd 的命令列出 Linux 系统上的所有服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl list-unit-files --type service -all</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_list_services.png?ssl=1" alt="systemctl list-unit-files"></p><p>此命令将输出所有服务的状态。服务状态有<ruby>启用<rt>enabled</rt></ruby>、<ruby>禁用<rt>disabled</rt></ruby>、<ruby>屏蔽<rt>masked</rt></ruby>（在取消屏蔽之前处于非活动状态）、<ruby>静态<rt>static</rt></ruby>和<ruby>已生成<rt>generated</rt></ruby>。</p>',10)),n("p",null,[s[6]||(s[6]=t("与 ",-1)),i(e,{href:"https://linuxhandbook.com/grep-command-examples/"},{default:a(()=>[...s[5]||(s[5]=[t("grep 命令",-1)])]),_:1}),s[7]||(s[7]=t(" 结合，你可以仅显示正在运行的服务：",-1))]),s[26]||(s[26]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl | grep running</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_grep_running.jpg?ssl=1" alt="Display running services systemctl"></p><p>现在，你知道了如何引用所有不同的服务，你可以开始主动管理它们。</p><p><strong>注意：</strong> 下列命令中的 <code>&lt;service-name&gt;</code> 应该用你想管理的服务名代替。（比如：network-manager、ufw 等）</p><h4 id="_2、启动服务" tabindex="-1">2、启动服务 <a class="header-anchor" href="#_2、启动服务" aria-label="Permalink to “2、启动服务”">​</a></h4><p>要在 Linux 中启动服务，你只需使用它的名字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start &lt;service-name&gt;</span></span></code></pre></div><h4 id="_3、停止服务" tabindex="-1">3、停止服务 <a class="header-anchor" href="#_3、停止服务" aria-label="Permalink to “3、停止服务”">​</a></h4><p>要停止 systemd 服务，可以使用 <code>systemctl</code> 命令的 <code>stop</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl stop &lt;service-name&gt;</span></span></code></pre></div><h4 id="_4、重启服务" tabindex="-1">4、重启服务 <a class="header-anchor" href="#_4、重启服务" aria-label="Permalink to “4、重启服务”">​</a></h4><p>要重启 systemd 服务，可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl restart &lt;service-name&gt;</span></span></code></pre></div><h4 id="_5、检查服务状态" tabindex="-1">5、检查服务状态 <a class="header-anchor" href="#_5、检查服务状态" aria-label="Permalink to “5、检查服务状态”">​</a></h4><p>你可以通过打印服务状态来确认你已经成功执行特定操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl status &lt;service-name&gt;</span></span></code></pre></div><p>这将以以下方式输出：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/12/systemctl_status.jpg?ssl=1" alt="systemctl status"></p><p>这是 systemd 的内容。现在切换到 init。</p><h3 id="方法-2-使用-init-在-linux-中管理服务" tabindex="-1">方法 2：使用 init 在 Linux 中管理服务 <a class="header-anchor" href="#方法-2-使用-init-在-linux-中管理服务" aria-label="Permalink to “方法 2：使用 init 在 Linux 中管理服务”">​</a></h3><p>init 的命令和 systemd 的一样简单。</p><h4 id="_1、列出所有服务-1" tabindex="-1">1、列出所有服务 <a class="header-anchor" href="#_1、列出所有服务-1" aria-label="Permalink to “1、列出所有服务”">​</a></h4><p>要列出所有 Linux 服务，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service --status-all</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/service_status_all.png?ssl=1" alt="service –status-all"></p><p>前面的 <code>[ – ]</code> 代表<strong>禁用</strong>，<code>[ + ]</code> 代表<strong>启用</strong>。</p><h4 id="_2、启动服务-1" tabindex="-1">2、启动服务 <a class="header-anchor" href="#_2、启动服务-1" aria-label="Permalink to “2、启动服务”">​</a></h4><p>要在 Ubuntu 和其他发行版中启动服务，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; start</span></span></code></pre></div><h4 id="_3、停止服务-1" tabindex="-1">3、停止服务 <a class="header-anchor" href="#_3、停止服务-1" aria-label="Permalink to “3、停止服务”">​</a></h4><p>停止服务同样简单。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; stop</span></span></code></pre></div><h4 id="_4、重启服务-1" tabindex="-1">4、重启服务 <a class="header-anchor" href="#_4、重启服务-1" aria-label="Permalink to “4、重启服务”">​</a></h4><p>如果你想重启服务，命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; restart</span></span></code></pre></div><h4 id="_5、检查服务状态-1" tabindex="-1">5、检查服务状态 <a class="header-anchor" href="#_5、检查服务状态-1" aria-label="Permalink to “5、检查服务状态”">​</a></h4><p>此外，要检查是否达到了预期的结果，你可以输出服务状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>service &lt;service-name&gt; status</span></span></code></pre></div><p>这将以以下方式输出：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/12/service_status.jpg?ssl=1" alt="service status"></p><p>最重要的是，这将告诉你某项服务是否处于活跃状态（正在运行）。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>今天，我详细介绍了两种在 Ubuntu 或任何其他 Linux 系统上管理服务的非常简单的方法。 希望本文对你有所帮助。</p><p>你更喜欢哪种方法？ 让我在下面的评论中知道！</p><hr>',45)),n("p",null,[s[9]||(s[9]=t("via: ",-1)),i(e,{href:"https://itsfoss.com/start-stop-restart-services-linux/"},{default:a(()=>[...s[8]||(s[8]=[t("https://itsfoss.com/start-stop-restart-services-linux/",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=t("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sergiu/"},{default:a(()=>[...s[10]||(s[10]=[t("Sergiu",-1)])]),_:1}),s[15]||(s[15]=t(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[11]||(s[11]=[t("lujun9972",-1)])]),_:1}),s[16]||(s[16]=t(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[12]||(s[12]=[t("geekpi",-1)])]),_:1}),s[17]||(s[17]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[13]||(s[13]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[18]||(s[18]=[t("LCTT",-1)])]),_:1}),s[21]||(s[21]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[19]||(s[19]=[t("Linux中国",-1)])]),_:1}),s[22]||(s[22]=t(" 荣誉推出",-1))])])}const v=r(u,[["render",h]]);export{x as __pageData,v as default};
